      patches[e.gimmick] = { ...(patches[e.gimmick] ?? {}), ...e.patch };
      if (e.patch.dwellMs && g.room.world.gimmicks[e.gimmick]) g.room.world.gimmicks[e.gimmick].dwellMs = e.patch.dwellMs;
