// Stage machine: lobby → intro → day1 → night1 → … → day5 → night5 → final → result.
// It knows nothing about time; see timing.js.

const TOTAL_DAYS = 5;
const STAGES = ['lobby', 'intro', 'day', 'night', 'final', 'result'];

function nextStage(stage, day) {
  switch (stage) {
    case 'lobby': return { stage: 'intro', day: 0 };
    case 'intro': return { stage: 'day', day: 1 };
    case 'day': return { stage: 'night', day };
    case 'night': return day < TOTAL_DAYS ? { stage: 'day', day: day + 1 } : { stage: 'final', day };
    default: return null; // final → result happens only by submitting answers
  }
}

function stageLabel(stage, day) {
  switch (stage) {
    case 'lobby': return '대기실';
    case 'intro': return '사건 소개';
    case 'day': return `${day}일 차 낮`;
    case 'night': return `${day}일 차 밤`;
    case 'final': return '최종 추리';
    case 'result': return '결과';
    default: return stage;
  }
}

// Korean particle after a word: 이/가, 으로/로 depend on the last syllable's final consonant.
function particle(word, [withFinal, withoutFinal]) {
  const code = word.charCodeAt(word.length - 1) - 0xac00;
  if (code < 0 || code > 11171) return `${withFinal}(${withoutFinal})`;
  const final = code % 28;
  if (withFinal === '으로' && final === 8) return withoutFinal; // ㄹ takes 로
  return final ? withFinal : withoutFinal;
}

// For dev jumps: is (stage, day) a position the normal flow can reach before submitting?
function isReachable(stage, day) {
  if (stage === 'intro') return day === 0;
  if (stage === 'day' || stage === 'night') return Number.isInteger(day) && day >= 1 && day <= TOTAL_DAYS;
  if (stage === 'final') return day === TOTAL_DAYS;
  return false;
}

module.exports = { TOTAL_DAYS, STAGES, nextStage, stageLabel, isReachable, particle };

