// placements: times the team put on cards that carry none (timeline); suspects: the suspect table
const emptyBoard = () => ({ clues: {}, notes: {}, noteSeq: 0, verdicts: {}, placements: {}, suspects: {} });
const emptyFinal = () => ({ draft: { answers: {}, evidence: {}, rev: 0, updatedBy: null, updatedAt: null }, submitted: null });

